if (points.size() < 3) {
    throw std::runtime_error("At least 3 points are required to define a plane");
}

Kernel::Point_3 centroid(0, 0, 0);
for (const auto& p : points) {
    centroid += p;
}
centroid /= static_cast<double>(points.size());

std::vector<Kernel::Vector_3> translated_points;
for (const auto& p : points) {
    translated_points.push_back(p - centroid);
}

Kernel::Matrix<3, 3, double> H(0);
for (const auto& v : translated_points) {
    H += std::outer_product(v, v);
}

Kernel::Matrix<3, 1, double> b(0);
for (const auto& v : translated_points) {
    b += v;
}

Kernel::Matrix<3, 3, double> H_inv = H.inverse();
Kernel::Matrix<3, 1, double> n = H_inv * b;

Kernel::Plane_3 plane(n(0), n(1), n(2), centroid);
return plane;
// END_CODE

